package com.smarthub.plus;
import android.content.*;
import android.content.pm.*;
import android.database.Cursor;
import android.media.tv.*;
import android.os.*;
import android.widget.*;
import java.util.*;
public final class ReceiverActivity extends HubActivity {
 private LinearLayout nativeChannels;
 @Override public void onCreate(Bundle s){super.onCreate(s);LinearLayout body=page(tx("الرسيفر والتطبيقات","Receiver & TV apps"),tx("فحص الواجهات المتاحة فعلياً على الجهاز","Inspect the interfaces actually available on this device"));LinearLayout info=card(body);info.addView(text(Build.MANUFACTURER+"  "+Build.MODEL+" • Android "+Build.VERSION.RELEASE,20,true));note(info,tx("هذه الصفحة تفحص واجهة Android TV العامة فقط. مساعد القنوات الفضائية يقرأ السياق المتاح من الرسيفر أو شاشة معلوماته، مع دليل XMLTV اختياري. بعض مسارات تعديل قاعدة قنوات المصنع تتطلب صلاحياته الموقّعة؛ قراءة إعدادات أو أقفال لا تعني توفر قائمة القنوات وEPG.","This page inspects the public Android TV interface. The satellite companion uses context exposed by the receiver or its information banner, with optional XMLTV. Some vendor channel-editing interfaces require manufacturer signature permissions; readable settings or locks are not a channel/EPG catalogue."));action(info,tx("فتح مساعد القنوات الفضائية","Open satellite TV companion"),()->startActivity(new Intent(this,SatelliteActivity.class)));action(info,tx("تحديث قائمة قنوات النظام","Refresh system channel list"),this::scan);nativeChannels=card(body);scan();LinearLayout apps=card(body);apps.addView(text(tx("فتح تطبيقات التلفاز المثبتة","Open installed TV apps"),21,true));Intent leanback=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);List<ResolveInfo> installed=getPackageManager().queryIntentActivities(leanback,0);Collections.sort(installed,(a,b)->a.loadLabel(getPackageManager()).toString().compareToIgnoreCase(b.loadLabel(getPackageManager()).toString()));for(ResolveInfo result:installed){if(result.activityInfo.packageName.equals(getPackageName()))continue;String label=result.loadLabel(getPackageManager()).toString();action(apps,label,()->{try{startActivity(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(result.activityInfo.packageName,result.activityInfo.name)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){toast(tx("تعذر فتح التطبيق","Could not open app"));}});}if(installed.isEmpty())note(apps,tx("لم تُكتشف تطبيقات بواجهة Android TV","No Android TV launchers discovered"));}
 private void scan(){if(nativeChannels==null)return;nativeChannels.removeAllViews();int count=0;try(Cursor cursor=getContentResolver().query(TvContract.Channels.CONTENT_URI,new String[]{"_id","display_name","display_number"},null,null,null)){if(cursor!=null)while(cursor.moveToNext()&&count<500){long id=cursor.getLong(0);String name=cursor.getString(1),number=cursor.getString(2);action(nativeChannels,(number==null?"":number)+"   "+name,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,TvContract.buildChannelUri(id)));}catch(Exception e){toast(tx("لا يتوفر مشغل لهذه القناة","No player handles this channel"));}});count++;}}catch(SecurityException denied){note(nativeChannels,tx("واجهة Android TV العامة لا تسمح لهذا التطبيق بقراءة قنواتها. افتح مساعد القنوات للربط عبر معلومات الرسيفر المتاحة.","The public Android TV interface denied this channel query. Open the companion to use the receiver information it exposes."));return;}catch(Exception e){note(nativeChannels,tx("واجهة القنوات غير متاحة: ","Channel interface unavailable: ")+e.getClass().getSimpleName());return;}if(count==0)note(nativeChannels,tx("لم تنشر واجهة Android TV العامة قنوات هنا. افتح مساعد القنوات، وأظهر شريط INFO أو EPG في تطبيق الرسيفر، أو اربط دليل XMLTV.","No channels were published through this public Android TV interface. Open the companion and show the receiver INFO banner or EPG, or map an XMLTV guide."));}
}
